-- TR1 V2: Editorial enrichment from official VK SWISS product pages, consulted 2026-11-22.
-- The records remain unpublished and their prices remain unverified. Legal/label review is required.
alter table public.products add column if not exists editorial_source_url text;
alter table public.products add column if not exists editorial_checked_at timestamptz;
with editorial(sku,source_url,description,actives,inci,usage_advice,precautions) as (
 values
 ('6467333','https://www.vk-swiss.ch/ashwagandha-ghee','Complément alimentaire VK SWISS associant l’extrait de racines d’ashwagandha KSM-66® et du ghee issu de lait suisse, présenté en boîte de 30 gélules.','Extrait d’ashwagandha bio : 340 mg, KSM-66® standardisé à 5 % de withanolides ; ghee suisse : 510 mg (quantités annoncées par la marque).','Contenu : ghee (matière grasse laitière anhydre, lait) 510 mg, extrait d’ashwagandha bio 340 mg, huile de colza raffinée, lécithine de tournesol. Enveloppe : gélatine de poisson, glycérol, eau, sorbitol. Allergènes : lait, poisson.','Selon la marque : 1 gélule par jour avec du liquide.','La marque recommande un avis spécialisé pour les femmes enceintes ou allaitantes, les moins de 16 ans et toute personne sous traitement médical. Ne pas dépasser la quantité recommandée. Tenir hors de portée des enfants. Un complément alimentaire ne remplace pas une alimentation variée.'),
 ('6467332','https://www.vk-swiss.ch/bacopa-ghee','Complément alimentaire VK SWISS associant un extrait de Bacopa monnieri et du ghee suisse, présenté en boîte de 30 gélules.','Extrait de Bacopa monnieri : 200 mg (annoncé par la marque comme standardisé à 20 % de bacosides) ; ghee suisse : 500 mg.','Contenu : ghee (matière grasse laitière anhydre, lait) 500 mg, huile de colza, extrait de Bacopa monnieri 200 mg, lécithine de tournesol. Enveloppe : gélatine de poisson, glycérol, eau, sorbitol. Allergènes : lait, poisson.','Selon la marque : 1 gélule par jour avec du liquide.','Réservé à l’adulte. Déconseillé pendant la grossesse ou l’allaitement et en cas de prise de sédatifs, antidépresseurs ou anticonvulsivants. Demander conseil en cas de traitement médical ; prudence pour la conduite. Réduire ou arrêter en cas de troubles digestifs. Ne pas dépasser la dose indiquée. Tenir hors de portée des enfants.'),
 ('6467334','https://www.vk-swiss.ch/curcuma-ghee','Complément alimentaire VK SWISS associant du curcuma, de la pipérine issue du poivre noir et du ghee suisse, présenté en boîte de 30 gélules.','Poudre de curcuma : 340 mg ; ghee suisse : 493 mg ; pipérine (extrait de poivre noir, quantité non précisée sur la fiche consultée).','Contenu : ghee (matière grasse laitière anhydre, lait) 493 mg, curcuma en poudre 340 mg, pipérine (extrait de poivre noir), huile de colza raffinée, lécithine de tournesol. Enveloppe : gélatine de poisson, glycérol, eau, sorbitol. Allergènes : lait, poisson.','Selon la marque : 1 gélule par jour avec du liquide.','Réservé à l’adulte. Déconseillé pendant la grossesse ou l’allaitement, en cas de maladie de Crohn ou de pathologie biliaire, et avec certains traitements (anticoagulants, anticancéreux, immunosuppresseurs). Demander conseil à un professionnel de santé sous traitement médical. Ne pas dépasser la dose indiquée. Tenir hors de portée des enfants.'),
 ('6467330','https://www.vk-swiss.ch/shatavari-ghee','Complément alimentaire VK SWISS associant de la poudre de Shatavari (Asparagus racemosus) et du ghee suisse, présenté en boîte de 30 gélules.','Poudre de Shatavari (Asparagus racemosus Willd.) : 350 mg ; ghee suisse : 420 mg.','Contenu : huile de colza, ghee (matière grasse laitière anhydre, lait) 420 mg, poudre de Shatavari 350 mg, lécithine de tournesol. Enveloppe : gélatine de poisson, glycérol, eau, sorbitol. Allergènes : lait, poisson.','Selon la marque : 1 gélule par jour avec du liquide.','Déconseillé aux femmes enceintes ou allaitantes, aux moins de 16 ans, aux personnes atteintes d’un cancer hormonodépendant ou de troubles de la coagulation. Demander conseil en cas de traitement médical. Ne pas dépasser la dose indiquée. Tenir hors de portée des enfants.'),
 ('6467328','https://www.vk-swiss.ch/shilajit-ghee','Complément alimentaire VK SWISS associant un extrait de shilajit et du ghee suisse, présenté en boîte de 30 gélules.','Extrait de shilajit (Asphaltum punjabianum) : 340 mg, dont acide fulvique 170 mg ; ghee suisse : 500 mg.','Contenu : ghee (matière grasse laitière anhydre, lait) 500 mg, huile de colza, extrait de shilajit 340 mg (dont acide fulvique 170 mg), lécithine de tournesol. Enveloppe : gélatine de poisson, glycérol, eau, sorbitol. Allergènes : lait, poisson.','Selon la marque : 1 gélule par jour avec du liquide.','Déconseillé pendant la grossesse ou l’allaitement et aux moins de 16 ans. La marque recommande un avis médical en cas de traitement ou de maladie chronique, notamment troubles rénaux, hépatiques, thyroïdiens, diabète, hypertension, goutte ou troubles digestifs. Ne pas dépasser la dose indiquée. Tenir hors de portée des enfants.'),
 ('6467329','https://www.vk-swiss.ch/copie-de-shilajit-ghee','Complément alimentaire VK SWISS associant un extrait de Tribulus terrestris et du ghee suisse, présenté en boîte de 30 gélules.','Extrait de Tribulus terrestris : 350 mg, dont 315 mg de saponines ; ghee suisse : 500 mg.','Contenu : ghee (matière grasse laitière anhydre, lait) 500 mg, extrait de Tribulus terrestris 350 mg (dont saponines 315 mg), huile de colza, lécithine de tournesol. Enveloppe : gélatine de poisson, glycérol, eau, sorbitol. Allergènes : lait, poisson.','Selon la marque : 1 gélule par jour avec du liquide.','La marque recommande un avis médical en cas de traitement ou de pathologie hormonodépendante. En cas de troubles digestifs ou d’agitation, réduire ou arrêter la prise. Ne pas dépasser la dose recommandée. Conserver hors de portée des enfants.')
)
update public.products p
set format='30 gélules',
 description=e.description,
 actives=e.actives,
 inci=e.inci,
 usage_advice=e.usage_advice,
 precautions=e.precautions,
 editorial_source_url=e.source_url,
 editorial_checked_at=now(),
 requires_review=true,
 price_verified=false,
 published=false
from editorial e
join public.brands b on b.slug='vk-swiss'
where p.brand_id=b.id and p.sku=e.sku and p.source_catalog='tr1_legacy_catalog' and p.published=false;
